WITH cleaned AS (SELECT id, account_id, txn_type, txn_time, merchant, is_flagged, IF(is_flagged, 'Yes', 'No') AS is_flagged_label, COALESCE(merchant, 'UNKNOWN') AS merchant_clean FROM transactions WHERE merchant IS NOT NULL), with_dims AS (SELECT e.*, d.balance, d.account_type FROM cleaned e LEFT JOIN accounts d ON e.account_id = d.id), scored AS (SELECT *, AVG(balance) OVER w_part AS balance_avg_3_prior, SUM(balance) OVER (PARTITION BY TO_DATE(txn_time), merchant ORDER BY balance, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_balance, NTILE(3) OVER w_recent AS balance_bucket, PERCENT_RANK() OVER (PARTITION BY txn_type ORDER BY balance) AS balance_percent_rank FROM with_dims WINDOW w_part AS (PARTITION BY merchant ORDER BY txn_time, id ROWS BETWEEN 3 PRECEDING AND 1 PRECEDING), w_recent AS (PARTITION BY txn_type ORDER BY balance, id)), ranked AS (SELECT id, txn_type, is_flagged, is_flagged_label, merchant_clean, balance, account_type, running_balance, balance_bucket FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY account_type ORDER BY balance DESC NULLS LAST, id) AS rn FROM scored) x WHERE rn = 1), scored_transactions AS (SELECT *, AVG(balance) OVER (PARTITION BY txn_type, account_type ORDER BY balance, id ROWS BETWEEN 2 PRECEDING AND 1 PRECEDING) AS balance_avg_2_prior, ROW_NUMBER() OVER (ORDER BY balance, id) AS seq_no, LAG(balance, 2, 0) OVER (PARTITION BY txn_type ORDER BY balance_bucket, id) AS prev_balance, MIN(balance_bucket) OVER (PARTITION BY account_type) AS account_type_min_balance_bucket FROM ranked), metrics AS (SELECT id, is_flagged, merchant_clean, balance, balance_avg_2_prior, seq_no, prev_balance, account_type_min_balance_bucket, ROUND(balance_bucket / SUM(balance_bucket) OVER (PARTITION BY txn_type), 4) AS balance_bucket_share, CUME_DIST() OVER (ORDER BY seq_no DESC NULLS LAST) AS seq_no_cume_dist FROM scored_transactions) SELECT id, is_flagged, merchant_clean, balance, seq_no, account_type_min_balance_bucket FROM metrics;
